import{$,$$,status,escape}from'./common.js';const roasts={daybreak:{name:'Daybreak',notes:'Chocolate · caramel · orange',description:'Comforting chocolate, a little caramel sweetness and a bright finish.',color:'#b95c3d',price:450},golden:{name:'Golden Hour',notes:'Peach · honey · jasmine',description:'A bright, floral cup with soft fruit notes and a honey finish.',color:'#b78a36',price:520},midnight:{name:'Midnight',notes:'Cocoa · walnut · molasses',description:'Rich cocoa, roasted nuts and a bold, comforting finish.',color:'#3b5451',price:480}};let quantity=1,cart=[];const money=n=>'₹'+n.toLocaleString('en-IN');const product=()=>{const key=$('#roast').value,r=roasts[key],size=+$('#bagSize').value;return{key,name:r.name,size,grind:$('#grind').value,price:Math.round(r.price*(size/250)*(size===1000?.9:size===500?.95:1))}};
function render(){const r=roasts[$('#roast').value],p=product();['hero','shop'].forEach(prefix=>{$('#'+prefix+'Bag').style.background=r.color;$('#'+prefix+'Roast').textContent=r.name.toUpperCase();$('#'+prefix+'Notes').textContent=r.notes;$('#'+prefix+'Weight').textContent=p.size+'G / FRESH POSSIBILITIES'});$('#roastDescription').textContent=r.description;$('#productPrice').textContent=money(p.price*quantity);$('#quantity').textContent=quantity;$('#decrease').disabled=quantity===1;$('#increase').disabled=quantity===20}
['roast','bagSize','grind'].forEach(id=>$('#'+id).oninput=()=>{render();status('')});$('#increase').onclick=()=>{if(quantity<20)quantity++;render()};$('#decrease').onclick=()=>{if(quantity>1)quantity--;render()};$('#addCart').onclick=()=>{const p=product(),item=cart.find(i=>i.key===p.key&&i.size===p.size&&i.grind===p.grind);if(item){item.quantity=Math.min(99,item.quantity+quantity)}else cart.push({...p,quantity});updateCart();status(quantity+' bag'+(quantity===1?'':'s')+' added to your demo cart.')};
const dialog=$('#cartDialog');$('#viewCart').onclick=()=>{updateCart();$('#checkoutResult').textContent='';dialog.showModal()};$('.dialog-close').onclick=()=>dialog.close();function updateCart(){$('#cartCount').textContent=cart.reduce((n,i)=>n+i.quantity,0);$('#cartItems').replaceChildren();if(!cart.length){const li=document.createElement('li');li.textContent='Your demo cart is empty.';$('#cartItems').append(li)}cart.forEach((item,i)=>{const li=document.createElement('li');li.innerHTML=`<span><b>${escape(item.name)}</b><br>${item.size} g / ${escape(item.grind)}<br>${money(item.price*item.quantity)}</span><button data-minus aria-label="Reduce ${escape(item.name)} quantity">−</button><small>${item.quantity}</small><button data-plus aria-label="Increase ${escape(item.name)} quantity">+</button><button data-remove aria-label="Remove ${escape(item.name)}">×</button>`;li.querySelector('[data-minus]').onclick=()=>{item.quantity--;if(item.quantity===0)cart.splice(i,1);updateCart()};li.querySelector('[data-plus]').onclick=()=>{item.quantity=Math.min(99,item.quantity+1);updateCart()};li.querySelector('[data-remove]').onclick=()=>{cart.splice(i,1);updateCart()};$('#cartItems').append(li)});$('#cartTotal').textContent=money(cart.reduce((n,i)=>n+i.price*i.quantity,0));$('#checkout').disabled=!cart.length}$('#checkout').onclick=()=>{$('#checkoutResult').textContent='Demo checkout preview: '+cart.reduce((n,i)=>n+i.quantity,0)+' bags, '+money(cart.reduce((n,i)=>n+i.price*i.quantity,0))+'. No order or payment was placed.'};render();updateCart();
